class Solution:
    def sortTheStudents(self, score: list[list[int]], k: int) -> list[list[int]]:
        return sorted(score, key=lambda row: row[k], reverse=True)

class Solution {
public:
    std::vector<std::vector<int>> sortTheStudents(std::vector<std::vector<int>>& score, int k) {
        std::sort(score.begin(), score.end(), [k](const auto& a, const auto& b) {
            return a[k] > b[k];
        });
        return score;
    }
};

class Solution {
    public int[][] sortTheStudents(int[][] score, int k) {
        java.util.Arrays.sort(score, (a, b) -> Integer.compare(b[k], a[k]));
        return score;
    }
}

var sortTheStudents = function(score, k) {
    return score.slice().sort((a, b) => b[k] - a[k]);
};
